const ICON_PNG = /(^|\/)assets\/sprites\/icons\/([a-z0-9_]+)\.png(\?.*)?$/;

/** The @3x URL for an icon PNG URL, or null. */
export function hiresIconUrl(url) {
  const m = ICON_PNG.exec(String(url || ''));
  if (!m || !HIRES_ICONS.has(m[2])) return null;
  return String(url).replace(/\.png(\?.*)?$/, '@3x.png$1');
}

/**
 * Serve the 3x icons everywhere at their original size: js/textures.js loads
 * the `@3x` file (resolution 3 from the name), and icon <img> elements get a
 * `3x` srcset (kept in step when their src changes).
 * @param {{ addUrlRoute: Function }} textures the js/textures.js module
 */
export function installHiresIcons(textures, root = globalThis.document) {
  if (typeof textures?.addUrlRoute === 'function') textures.addUrlRoute('hires-icons', hiresIconUrl);
  if (!root?.body || typeof MutationObserver === 'undefined') return;
  const upgrade = (img) => {
    const hi = hiresIconUrl(img.getAttribute('src'));
    if (hi) {
      const set = `${hi} 3x`;
      if (img.getAttribute('srcset') !== set) img.setAttribute('srcset', set);
      img.dataset.hiresIcon = '1';
    } else if (img.dataset.hiresIcon) {
      img.removeAttribute('srcset');
      delete img.dataset.hiresIcon;
    }
  };
  const scan = (node) => {
    if (node.nodeType !== 1) return;
    if (node.tagName === 'IMG') upgrade(node);
    else if (node.getElementsByTagName) for (const img of node.getElementsByTagName('img')) upgrade(img);
  };
  scan(root.body);
  new MutationObserver((records) => {
    for (const record of records) {
      if (record.type === 'attributes') upgrade(record.target);
      else for (const node of record.addedNodes) scan(node);
    }
  }).observe(root.body, { subtree: true, childList: true, attributes: true, attributeFilter: ['src'] });
}
